## Why This Is Asked
Tests ability to combine subarray maxima with partition DP, requiring both maximization and reconstruction of multiple intervals. It exercises careful indexing and boundary handling.

## Key Concepts
- Non-overlapping subarrays with a cap k
- Precomputation of maxSub for O(1) subarray maxima
- 2D DP with reconstruction pointers
- Time/space tradeoffs and edge cases (k=0, equal values)

## Code Example
```javascript
function maxValueWithKSubarrays(A, k) {
  const n = A.length;
  const maxSub = Array.from({length: n}, () => Array(n).fill(0));
  for (let l = 0; l < n; l++) {
    let m = -Infinity;
    for (let r = l; r < n; r++) {
      m = Math.max(m, A[r]);
      maxSub[l][r] = m;
    }
  }
  const dp = Array.from({length: n+1}, () => Array(k+1).fill(0));
  const take = Array.from({length: n+1}, () => Array(k+1).fill(-1));
  for (let i = 1; i <= n; i++) {
    for (let t = 1; t <= k; t++) {
      let best = dp[i-1][t];
      let bestJ = -1;
      for (let j = 1; j <= i; j++) {
        const val = maxSub[j-1][i-1] + dp[j-1][t-1];
        if (val > best) { best = val; bestJ = j; }
      }
      dp[i][t] = best; take[i][t] = bestJ;
    }
  }
  const res = [];
  let i = n, t = k;
  while (t > 0 && i > 0) {
    const j = take[i][t];
    if (j === -1) break;
    res.push([j-1, i-1]);
    i = j - 1;
    t--;
  }
  res.reverse();
  return {value: dp[n][k], subarrays: res};
}
```

## Why This Is Asked
Tests concrete DP skills on string partitioning with reconstruction; approachable for beginners yet non-trivial.

## Key Concepts
- dp[i][t]: maximum sum for first i digits split into t parts
- val(j,i): integer value of s[j..i-1] (leading zeros allowed)
- transition: dp[i][t] = max_{j ∈ [t-1..i-1]} dp[j][t-1] + val(j,i)
- reconstruction: track prev to recover split indices
- complexity: O(n²k) time, O(nk) space; use BigInt for large results

## Code Example
```javascript
function maxSumSplit(s, k){
  const n = s.length;
  const val = (a,b)=> BigInt(s.slice(a,b));
  const dp = Array.from({length: n+1}, () => Array(k+1).fill(-1n));
  const prev = Array.from({length: n+1}, () => Array(k+1).fill(-1));

  for(let i=1;i<=n;i++){
    dp[i][1] = val(0,i);
  }

  for(let t=2;t<=k;t++){
    for(let i=t;i<=n;i++){
      for(let j=t-1;j<i;j++){
        const candidate = dp[j][t-1] + val(j,i);
        if(candidate > dp[i][t]){
          dp[i][t] = candidate;
          prev[i][t] = j;
        }
      }
    }
  }

  // Reconstruct splits
  const splits = [];
  let curr = n, parts = k;
  while(parts > 1){
    const j = prev[curr][parts];
    splits.push(j);
    curr = j;
    parts--;
  }
  splits.reverse();

  return {maxSum: dp[n][k], splits};
}
```

## Why This Is Asked
Tests DP state augmentation for a path with a constrained number of turns, combining path optimization with reconstruction. It demands careful handling of transitions when direction changes. 

## Key Concepts
- DP on grid paths with turn constraints
- 4D state dp[i][j][t][dir]
- Reconstruction via parent pointers
- Time: O(n*m*k); Space: O(n*m*k)

## Code Example
```javascript
function maxPathWithKTurns(grid, K) {
  const n = grid.length, m = grid[0].length;
  const NEG = -1e15;
  const dp = Array.from({length: n}, () =>
    Array.from({length: m}, () => Array.from({length: K+1}, () => [NEG, NEG]))
  );
  dp[0][0][0][0] = grid[0][0];
  dp[0][0][0][1] = grid[0][0];
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < m; j++) {
      if (i === 0 && j === 0) continue;
      for (let t = 0; t <= K; t++) {
        const val = grid[i][j];
        if (j > 0) {
          dp[i][j][t][0] = Math.max(dp[i][j][t][0], dp[i][j-1][t][0] + val);
          if (t > 0) dp[i][j][t][0] = Math.max(dp[i][j][t][0], dp[i][j-1][t-1][1] + val);
        }
        if (i > 0) {
          dp[i][j][t][1] = Math.max(dp[i][j][t][1], dp[i-1][j][t][1] + val);
          if (t > 0) dp[i][j][t][1] = Math.max(dp[i][j][t][1], dp[i-1][j][t-1][0] + val);
        }
      }
    }
  }
  // reconstruction would backtrack using stored choices (omitted for brevity)
  return {dp, best: Math.max(...Array.from({length:K+1}, (_,t)=>Math.max(dp[n-1][m-1][t][0], dp[n-1][m-1][t][1])))};
}
```

## Why This Question Is Asked

This problem evaluates proficiency in tree DP with disjoint-path packing and exact-path-count constraints, along with path reconstruction. It combines knapsack-on-tree techniques with path endpoint handling while guaranteeing vertex-disjointness.

## Key Concepts

- Tree DP with multiple states per node (unused vs. endpoint vs. interior)
- Knapsack-style merging across children via DP table convolution
- Path reconstruction through stored decision pointers

## Code Example

```javascript
function dfs(u, parent) {
    const dp0 = Array(k + 1).fill(-INF), dp1 = Array(k + 1).fill(-INF), dp2 = Array(k + 1).fill(-INF);
    dp0[u][0] = dp1[u][1] = 0;
    for (const v of children[u]) {
        dfs(v, u);
        const ndp0 = Array(k + 1).fill(-INF), ndp1 = Array(k + 1).fill(-INF), ndp2 = Array(k + 1).fill(-INF);
        for (let i = 0; i <= k; i++) for (let j = 0; j + i <= k; j++) {
            ndp0[i + j] = Math.max(ndp0[i + j], dp0[u][i] + max(dp0[v][j], dp1[v][j], dp2[v][j]));
            ndp1[i + j] = Math.max(ndp1[i + j], dp1[u][i] + max(dp0[v][j], dp2[v][j]));
            ndp2[i + j] = Math.max(ndp2[i + j], dp2[u][i] + dp0[v][j]);
        }
        dp0 = ndp0; dp1 = ndp1; dp2 = ndp2;
    }
}
```

## Why This Is Asked
Tests classic DP with an additional dimension (at most k intervals) and reconstruction—a common pattern in scheduling optimization problems.

## Key Concepts
- Weighted interval scheduling with a cardinality constraint (at most k intervals)
- Predecessor p(i) computed via binary search on sorted end times
- DP table with an extra dimension tracking the number of selected intervals
- Backtracking reconstruction to output the chosen jobs

## Code Example
```javascript
function maxValueKJobs(jobs, k) {
  const sorted = jobs.map((j, idx) => ({ ...j, idx })).sort((a, b) => a.end - b.end);
  const n = sorted.length;
  const ends = sorted.map(j => j.end);

  const p = (i) => {
    let lo = 0, hi = i - 1;
    while (lo <= hi) {
      const mid = Math.floor((lo + hi) / 2);
      if (ends[mid] <= sorted[i].start) lo = mid + 1;
      else hi = mid - 1;
    }
    return hi;
  };

  const dp = Array.from({ length: n + 1 }, () => Array(k + 1).fill(0));
  for (let i = 1; i <= n; i++) {
    for (let t = 1; t <= k; t++) {
      const prev = p(i - 1) + 1;
      dp[i][t] = Math.max(dp[i - 1][t], dp[prev][t - 1] + sorted[i - 1].value);
    }
  }

  const selected = [];
  let t = k;
  for (let i = n; i > 0 && t > 0; i--) {
    if (dp[i][t] !== dp[i - 1][t]) {
      selected.push(sorted[i - 1]);
      t--;
    }
  }

  return { value: dp[n][k], jobs: selected.reverse() };
}
```

## Why This Is Asked
This problem tests DP skills with an additional dimension for tracking turns while handling obstacles and grid boundaries. It verifies understanding of initialization logic, edge cases, and how to aggregate the final answer by summing across valid turn counts.

## Key Concepts
- 4D DP over cells, turn count, and last direction
- Turn counting via direction changes during transitions
- Correct handling of obstacles and grid boundaries
- Time/space trade-offs and proper base case logic

## Code Example
```javascript
function countPaths(grid, K) {
  const m = grid.length;
  const n = grid[0].length;
  if (grid[0][0] === 1 || grid[m-1][n-1] === 1) return 0;

  const dp = Array.from({ length: m }, () =>
    Array.from({ length: n }, () =>
      Array.from({ length: K + 1 }, () => [0, 0])
    )
  );

  dp[0][0][0][0] = 1; // right
  dp[0][0][0][1] = 1; // down

  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      if (grid[i][j] === 1) continue;
      for (let t = 0; t <= K; t++) {
        // from left (coming from right)
        if (j > 0) {
          dp[i][j][t][0] += dp[i][j-1][t][0]; // same direction
          if (t > 0) dp[i][j][t][0] += dp[i][j-1][t-1][1]; // turn
        }
        // from top (coming from down)
        if (i > 0) {
          dp[i][j][t][1] += dp[i-1][j][t][1]; // same direction
          if (t > 0) dp[i][j][t][1] += dp[i-1][j][t-1][0]; // turn
        }
      }
    }
  }

  let ans = 0;
  for (let t = 0; t <= K; t++) {
    ans += dp[m-1][n-1][t][0] + dp[m-1][n-1][t][1];
  }
  return ans;
}
```

This runs in O(m × n × K) time and O(m × n × K) space.

## Why This Is Asked
This tests a practical DP pattern: partitioning a string into k+1 substrings with a sum objective and exact k cuts, including reconstruction.

## Key Concepts
- DP over prefixes with exact cuts
- Substring value computation via prefix powers of 10
- Backtracking to recover split points

## Code Example
```javascript
function maxSumPartition(s, k){
  const n = s.length;
  const a = s.split('').map(Number);
  const pref = new Array(n+1).fill(0);
  const pow10 = new Array(n+1).fill(1);
  for(let i=1;i<=n;i++){pref[i] = pref[i-1]*10 + a[i-1]; pow10[i] = pow10[i-1]*10;}
  const val = (l,r)=> pref[r]-pref[l-1]*pow10[r-l+1];
  const dp = Array.from({length:n+1},()=>Array(k+1).fill(-Infinity));
  const pre = Array.from({length:n+1},()=>Array(k+1).fill(-1));
  for(let i=1;i<=n;i++){ dp[i][0] = val(1,i); }
  for(let t=1;t<=k;t++){
    for(let i=1;i<=n;i++){
      for(let j=0;j<i;j++){
        if(dp[j][t-1]===-Infinity) continue;
        const cur = dp[j][t-1] + val(j+1,i);
        if(cur>dp[i][t]){ dp[i][t]=cur; pre[i][t]=j; }
      }
    }
  }
  // reconstruct using n and k
  let cuts=[]; let i=n, t=k; while(t>0){ const j=pre[i][t]; cuts.push(j); i=j; t--; }
  cuts.reverse();
  return {sum: dp[n][k], cuts};
}
```

